package checkout.shipping;

import java.util.Locale;

public final class ShippingQuote {
    public static int quoteCents(int weightGrams, String postalCode) {
        if (weightGrams <= 0) {
            throw new IllegalArgumentException("weightGrams must be positive");
        }
        if (postalCode == null) {
            throw new IllegalArgumentException("postalCode must be non-blank");
        }

        String normalized = postalCode.trim().toUpperCase(Locale.ROOT);
        if (normalized.isEmpty()) {
            throw new IllegalArgumentException("postalCode must be non-blank");
        }

        long base;
        long perBlock;
        if (normalized.startsWith("AU")) {
            base = 450L;
            perBlock = 120L;
        } else if (normalized.startsWith("NZ")) {
            base = 850L;
            perBlock = 210L;
        } else if (normalized.startsWith("INTL")) {
            base = 1800L;
            perBlock = 450L;
        } else {
            throw new IllegalArgumentException("Unsupported postal code prefix");
        }

        long blocks = (weightGrams + 499L) / 500L;
        long total = base + perBlock * blocks;
        if (total > Integer.MAX_VALUE) {
            throw new ArithmeticException("total exceeds Integer.MAX_VALUE");
        }
        return (int) total;
    }
}
